    [505] = { id = 505, name = "Obtain a Support Job", amount_needed = 1, sparks = 100, exp = 500, description = "Speak to Isacio in Selbina (G-10) and complete the quest \"Elder Memories\" or speak to Vera in Mhaura (G-10) and complete the quest \"The Old Lady\" to obtain a support job. Requirement: Be level 18 or higher." },
    [506] = { id = 506, name = "Obtain an Alter Ego: San d'Oria", amount_needed = 1, sparks = 100, exp = 500, description = "Speak to Gondebaud in Southern San d'Oria (L-6), complete the quest \"Trust: San d'Oria,\" and obtain an alter ego of Excenmille. Requirement: Be level 5 or higher." },
    [507] = { id = 507, name = "Obtain an Alter Ego: Bastok", amount_needed = 1, sparks = 100, exp = 500, description = "Speak to Clarion Star in Port Bastok (K-7), complete the quest \"Trust: Bastok,\" and obtain an alter ego of Naji. Requirement: Be level 5 or higher." },
