    [510] = { id = 510, name = "Obtain Job: Paladin", amount_needed = 1, sparks = 100, exp = 300, description = "Speak to Balasiel in Southern San d'Oria (F-7), complete the quest line that begins with \"A Squire's Test,\" and obtain the paladin job. Requirements: Be level 30 or higher, reputation of \"I mighta hearda somebody that went by that name\" or the like." },
    [511] = { id = 511, name = "Obtain Job: Dark Knight", amount_needed = 1, sparks = 100, exp = 300, description = "Speak to Gumbah in Bastok Mines (J-7), complete the quest \"Blade of Darkness,\" and obtain the dark knight job. Requirement: Be level 30 or higher." },
    [512] = { id = 512, name = "Obtain Job: Beastmaster", amount_needed = 1, sparks = 100, exp = 300, description = "Examine the Door: Merchant's House in Upper Jeuno (G-11), complete the quest line that begins with \"Save My Son,\" and obtain the beastmaster job. Requirements: Be level 30 or higher, Completion of \"Chocobo's Wounds.\"" },
    [513] = { id = 513, name = "Obtain Job: Bard", amount_needed = 1, sparks = 100, exp = 300, description = "Speak to Mertaire in Lower Jeuno (I-8), complete the quest line that begins with \"The Old Monument,\" and obtain the bard job. Requirement: Be level 30 or higher." },
